20	
21	    it("zaokragla w dol wartosci ponizej polowy", () => {
22	      // SPEC sekcja 3, "Przelicznik", przyklad z SPEC: 2,4 -> 2
23	      expect(awardPoints(24, 0)).toBe(2);
24	      expect(awardPoints(101, 0)).toBe(10); // 10,1 -> 10
25	    });
26	
