28	      // SPEC sekcja 3, "Przelicznik", przyklad z SPEC: 2,6 -> 3
29	      expect(awardPoints(26, 0)).toBe(3);
30	      expect(awardPoints(99, 0)).toBe(10); // 9,9 -> 10
31	      expect(awardPoints(36, 0)).toBe(4); // 3,6 -> 4
32	    });
33	
34	    it("przy dokladnej polowie zaokragla do liczby parzystej (metoda bankierska)", () => {
35	      // SPEC sekcja 3, "Przelicznik": zaokraglenie bankierskie,
36	      // przyklady z SPEC: 2,5 -> 2 oraz 3,5 -> 4
37	      expect(awardPoints(25, 0)).toBe(2); // 2,5 -> 2 (parzysta)
38	      expect(awardPoints(35, 0)).toBe(4); // 3,5 -> 4 (parzysta)
39	      expect(awardPoints(5, 0)).toBe(0); // 0,5 -> 0 (parzysta)
40	      expect(awardPoints(15, 0)).toBe(2); // 1,5 -> 2 (parzysta)
41	      expect(awardPoints(105, 0)).toBe(10); // 10,5 -> 10 (parzysta)
42	      expect(awardPoints(115, 0)).toBe(12); // 11,5 -> 12 (parzysta)
43	    });
44	  });
45	
46	  describe("mnoznik VIP", () => {
47	    it("podwaja punkty klientowi o sumie zakupow co najmniej 5000 zl", () => {
48	      // SPEC sekcja 3, "Mnoznik VIP": suma dotychczasowych zakupow
49	      // co najmniej 5000 zl -> podwojona liczba punktow
50	      expect(awardPoints(100, 5000)).toBe(20); // granica wlaczna: 10 * 2
51	      expect(awardPoints(100, 5000.01)).toBe(20);
52	      expect(awardPoints(100, 99999)).toBe(20);
53	    });
54	
55	    it("nie podwaja punktow ponizej progu VIP", () => {
56	      // SPEC sekcja 3, "Mnoznik VIP": prog to 5000 zl sumy zakupow
57	      expect(awardPoints(100, 0)).toBe(10);
58	      expect(awardPoints(100, 4999.99)).toBe(10);
59	    });
60	
61	    it("stosuje mnoznik VIP do punktow po zaokragleniu bankierskim", () => {
62	      // SPEC sekcja 3: najpierw przelicznik z zaokragleniem bankierskim,
63	      // potem mnoznik VIP
64	      expect(awardPoints(35, 5000)).toBe(8); // 3,5 -> 4, VIP -> 8
65	      expect(awardPoints(25, 6000)).toBe(4); // 2,5 -> 2, VIP -> 4
66	    });
67	  });
68	
69	  describe("limit punktow", () => {
70	    it("ogranicza punkty do 5000 za jedno zamowienie", () => {
71	      // SPEC sekcja 3, "Limit": maksymalnie 5000 punktow za zamowienie
72	      expect(awardPoints(60000, 0)).toBe(5000); // 6000 -> limit
73	      expect(awardPoints(1000000, 0)).toBe(5000);
74	    });
75	
76	    it("stosuje limit po naliczeniu mnoznika VIP", () => {
77	      // SPEC sekcja 3, "Limit": "Limit stosujemy po naliczeniu mnoznika VIP"
78	      expect(awardPoints(30000, 9000)).toBe(5000); // 3000 * 2 = 6000 -> limit
79	      expect(awardPoints(25000, 9000)).toBe(5000); // 2500 * 2 = 5000 -> dokladnie limit
80	      expect(awardPoints(24000, 9000)).toBe(4800); // 2400 * 2 = 4800 -> bez limitu
81	    });
82	
83	    it("nie obniza wyniku rownego limitowi", () => {
84	      // SPEC sekcja 3, "Limit": limit to maksimum, wartosc 5000 jest dozwolona
85	      expect(awardPoints(50000, 0)).toBe(5000);
86	    });
87	  });
88	
89	  describe("walidacja", () => {
90	    it("odrzuca kwoty, ktore nie sa liczbami skonczonymi", () => {
91	      // SPEC sekcja 3, "Walidacja": ktorakolwiek kwota nie jest liczba
92	      // skonczona -> TypeError: amounts must be finite numbers
93	      const bad: unknown[] = [NaN, Infinity, -Infinity, "100", null, undefined, {}];
94	      for (const value of bad) {
95	        expect(() => awardPoints(value as number, 0)).toThrow(TypeError);
96	        expect(() => awardPoints(value as number, 0)).toThrow(
97	          "amounts must be finite numbers",
98	        );
99	        expect(() => awardPoints(100, value as number)).toThrow(TypeError);
100	        expect(() => awardPoints(100, value as number)).toThrow(
101	          "amounts must be finite numbers",
102	        );
103	      }
104	    });
105	
106	    it("odrzuca kwoty ujemne", () => {
